// Traducción al español de las recetas de recipes.js (mismo orden, mismo número de ingredientes y pasos).
window.DiaryRecipesI18n = window.DiaryRecipesI18n || {};
window.DiaryRecipesI18n.es = [
  {"t":"Gachas de avena con manzana","tempo":"10 min","por":"2 raciones","ing":["3 cucharadas soperas de copos de avena finos","150 ml de agua","1/2 manzana rallada","Una pizca de canela (opcional)"],"passos":["Pon la avena y el agua a fuego lento, removiendo, durante 5 minutos.","Añade la manzana rallada y deja cocer 2 minutos más.","Aromatiza con la canela y deja enfriar hasta que esté tibio."]},
  {"t":"Puré de calabaza y pera","tempo":"15 min","por":"4 raciones","ing":["200 g de calabaza pelada, en dados","1 pera madura","Un chorrito de aceite de oliva","Agua de la cocción, la necesaria"],"passos":["Cuece la calabaza al vapor durante 10 minutos, hasta que esté tierna.","Añade la pera pelada y troceada en los últimos 4 minutos.","Tritura con el aceite y un poco de agua hasta la textura que el bebé ya acepta.","Deja enfriar. Lo que sobre va al congelador en raciones."]},
  {"t":"Crema de calabacín y boniato","tempo":"20 min","por":"4 raciones","ing":["1 boniato pequeño","1/2 calabacín","1 chorrito de aceite de oliva","Agua, la necesaria"],"passos":["Pela y corta el boniato y el calabacín en dados.","Cuece en poca agua durante 15 minutos.","Tritura con el aceite, añadiendo agua de la cocción hasta que quede cremoso."]},
  {"t":"Plátano y aguacate chafados","tempo":"5 min","por":"1 ración","ing":["1/2 plátano maduro","1/4 de aguacate maduro"],"passos":["Chafa el plátano y el aguacate con un tenedor.","Mezcla bien hasta obtener una pasta lisa o con trocitos, según la etapa.","Sirve enseguida, para que no se oscurezca."]},
  {"t":"Puré de zanahoria y lentejas","tempo":"25 min","por":"4 raciones","ing":["2 zanahorias","2 cucharadas soperas de lentejas rojas","1/2 cebolla pequeña","Un chorrito de aceite de oliva"],"passos":["Enjuaga las lentejas con agua.","Cuece todo en agua durante 20 minutos, hasta que las lentejas se deshagan.","Tritura con el aceite y ajusta la textura con agua de la cocción."]},
  {"t":"Pollo con arroz y zanahoria","tempo":"30 min","por":"3 raciones","ing":["60 g de pechuga de pollo","2 cucharadas soperas de arroz","1 zanahoria","Un chorrito de aceite de oliva"],"passos":["Cuece el pollo, el arroz y la zanahoria en dados en agua, durante 20 minutos.","Comprueba que el pollo esté bien hecho por dentro.","Tritura o desmenuza, según la etapa del bebé, y añade el aceite."]},
  {"t":"Galletitas de avena y plátano","tempo":"20 min","por":"12 galletas","ing":["1 plátano bien maduro","60 g de copos de avena finos"],"passos":["Precalienta el horno a 180 °C.","Chafa el plátano y mézclalo con la avena hasta formar una masa.","Forma galletas finas en una bandeja con papel de horno.","Hornea 15 minutos y deja enfriar bien antes de dárselas."]},
  {"t":"Puré de zanahoria","tempo":"20 min","por":"4 raciones","ing":["3 zanahorias","Un chorrito de aceite de oliva","Agua de la cocción, la necesaria"],"passos":["Pela las zanahorias y córtalas en rodajas.","Cuece al vapor durante 15 minutos, hasta que estén bien tiernas.","Tritura con el aceite y un poco de agua de la cocción hasta que quede liso.","Congela lo que sobre en raciones pequeñas."]},
  {"t":"Sopa de calabaza, zanahoria y puerro","tempo":"25 min","por":"6 raciones","ing":["250 g de calabaza","1 zanahoria","1 patata pequeña","1/2 puerro (solo la parte blanca)","Un chorrito de aceite de oliva"],"passos":["Pela y trocea las verduras.","Cuece en agua que apenas las cubra, durante 20 minutos.","Tritura hasta que quede cremoso y añade el aceite ya fuera del fuego."]},
  {"t":"Puré de brócoli y patata","tempo":"20 min","por":"4 raciones","ing":["1 patata mediana","5 ramilletes de brócoli","Un chorrito de aceite de oliva"],"passos":["Pela la patata y córtala en dados.","Cuece la patata 10 minutos y añade el brócoli para 6 minutos más.","Tritura con el aceite y un poco de agua de la cocción."]},
  {"t":"Papilla de arroz con pera","tempo":"15 min","por":"2 raciones","ing":["3 cucharadas soperas de harina de arroz","150 ml de agua","1/2 pera madura"],"passos":["Disuelve la harina de arroz en el agua fría.","Ponla a fuego lento, sin dejar de remover, durante 5 minutos.","Añade la pera rallada muy fina y remueve 1 minuto más. Sirve tibia."]},
  {"t":"Manzana y pera cocidas","tempo":"15 min","por":"4 raciones","ing":["1 manzana","1 pera","Una pizca de canela (opcional)"],"passos":["Pela la fruta y córtala en dados.","Cuece al vapor de 8 a 10 minutos.","Chafa con un tenedor o tritura, y espolvorea con canela."]},
  {"t":"Puré de guisantes con hierbabuena","tempo":"15 min","por":"3 raciones","ing":["150 g de guisantes (pueden ser congelados)","1 patata pequeña","2 hojas de hierbabuena","Un chorrito de aceite de oliva"],"passos":["Cuece la patata en dados durante 8 minutos.","Añade los guisantes y cuece 5 minutos más.","Tritura con la hierbabuena y el aceite. Si quedan pieles, pásalo por el pasapurés."]},
  {"t":"Crema de coliflor y boniato","tempo":"20 min","por":"4 raciones","ing":["1 boniato pequeño","6 ramilletes de coliflor","Un chorrito de aceite de oliva"],"passos":["Pela el boniato y córtalo en dados.","Cuece todo en poca agua durante 15 minutos.","Tritura con el aceite hasta que quede aterciopelado."]},
  {"t":"Gachas de avena con plátano","tempo":"10 min","por":"2 raciones","ing":["3 cucharadas soperas de copos de avena finos","150 ml de agua o de la leche habitual del bebé","1/2 plátano maduro"],"passos":["Cuece la avena en el líquido, a fuego lento, durante 5 minutos.","Chafa el plátano y añádelo a las gachas.","Remueve bien y deja enfriar hasta que esté tibio."]},
  {"t":"Puré de mango","tempo":"5 min","por":"2 raciones","ing":["1/2 mango bien maduro"],"passos":["Pela el mango y saca la pulpa de alrededor del hueso.","Tritura o chafa con un tenedor hasta que quede liso.","Sirve enseguida o congela en raciones pequeñas."]},
  {"t":"Sopa de verduras de la abuela","tempo":"30 min","por":"6 raciones","ing":["1 patata","1 zanahoria","1/2 calabacín","1/4 de cebolla","Un chorrito de aceite de oliva"],"passos":["Pela y trocea todas las verduras.","Cuece en agua que apenas las cubra, durante 25 minutos.","Tritura y añade el aceite en crudo al final. Congela el resto en raciones."]},
  {"t":"Sopa de verduras con pavo","tempo":"30 min","por":"4 raciones","ing":["40 g de pechuga de pavo","1 patata","1 zanahoria","1/2 calabacín","Un chorrito de aceite de oliva"],"passos":["Cuece las verduras troceadas y el pavo entero durante 25 minutos.","Comprueba que el pavo esté bien hecho por dentro.","Tritura todo junto y añade el aceite al final."]},
  {"t":"Merluza con patata y brócoli","tempo":"25 min","por":"3 raciones","ing":["50 g de filete de merluza sin piel ni espinas","1 patata","4 ramilletes de brócoli","Un chorrito de aceite de oliva"],"passos":["Cuece la patata en dados durante 10 minutos.","Añade la merluza y el brócoli y cuece 8 minutos más.","Comprueba que no haya espinas, tritura o chafa y añade el aceite."]},
  {"t":"Lentejas con calabaza y arroz","tempo":"30 min","por":"4 raciones","ing":["2 cucharadas soperas de lentejas rojas","1 cucharada sopera de arroz","150 g de calabaza","Un chorrito de aceite de oliva","Una pizca de cúrcuma (opcional)"],"passos":["Enjuaga las lentejas y el arroz con agua.","Cuece todo con la calabaza en dados durante 25 minutos, hasta que quede bien tierno.","Tritura o chafa, añade el aceite y la cúrcuma."]},
  {"t":"Puré de garbanzos y zanahoria","tempo":"20 min","por":"4 raciones","ing":["100 g de garbanzos cocidos (sin sal, bien enjuagados)","2 zanahorias","Un chorrito de aceite de oliva","Una pizca de comino (opcional)"],"passos":["Cuece las zanahorias en rodajas durante 15 minutos.","Añade los garbanzos en los últimos 3 minutos para calentarlos.","Tritura con el aceite y un poco de agua hasta que quede cremoso, sin pieles."]},
  {"t":"Gachas de avena con pera y canela","tempo":"10 min","por":"2 raciones","ing":["3 cucharadas soperas de copos de avena","150 ml de la leche habitual del bebé o agua","1/2 pera","Una pizca de canela"],"passos":["Cuece la avena en el líquido durante 5 minutos, a fuego lento.","Añade la pera rallada y cuece 2 minutos más.","Espolvorea con canela y sirve tibio."]},
  {"t":"Salmón con boniato","tempo":"25 min","por":"3 raciones","ing":["50 g de salmón sin piel ni espinas","1 boniato pequeño","Un chorrito de aceite de oliva","Eneldo o perejil picado (opcional)"],"passos":["Cuece el boniato en dados durante 12 minutos.","Añade el salmón y cuece 6 minutos más, hasta que se separe en lascas con facilidad.","Comprueba que no haya espinas y chafa con el aceite y las hierbas."]},
  {"t":"Ternera estofada con verduras","tempo":"40 min","por":"4 raciones","ing":["60 g de carne de ternera magra en dados","1 patata","1 zanahoria","1/4 de cebolla","Un chorrito de aceite de oliva"],"passos":["Dora la cebolla en un chorrito de aceite de oliva y añade la carne.","Incorpora las verduras en dados y agua hasta cubrir.","Deja estofar 35 minutos a fuego lento, hasta que la carne esté tierna.","Tritura o desmenuza bien, según la etapa."]},
  {"t":"Sopa de guisantes con pollo","tempo":"25 min","por":"4 raciones","ing":["40 g de pechuga de pollo","100 g de guisantes","1 patata","Un chorrito de aceite de oliva"],"passos":["Cuece el pollo y la patata en dados durante 15 minutos.","Añade los guisantes y cuece 5 minutos más.","Tritura todo y añade el aceite."]},
  {"t":"Puré de remolacha y manzana","tempo":"30 min","por":"4 raciones","ing":["1 remolacha pequeña","1 manzana","1 patata pequeña"],"passos":["Pela y corta todo en dados.","Cuece la remolacha y la patata 20 minutos y añade la manzana en los últimos 5.","Tritura hasta que quede liso. Usa un babero: ¡la remolacha mancha!"]},
  {"t":"Pasta de sopa con calabacín y pavo","tempo":"20 min","por":"3 raciones","ing":["2 cucharadas soperas de pasta de estrellitas","40 g de pechuga de pavo","1/2 calabacín","Un chorrito de aceite de oliva"],"passos":["Cuece el pavo y el calabacín en dados durante 12 minutos.","Tritura con un poco de agua de la cocción.","Cuece la pasta aparte y mézclala con la crema. Añade el aceite."]},
  {"t":"Ciruela y pera cocidas","tempo":"15 min","por":"3 raciones","ing":["3 ciruelas maduras","1 pera"],"passos":["Pela la fruta y quita los huesos.","Cuece al vapor durante 8 minutos.","Tritura o chafa. Ayuda cuando el intestino anda perezoso."]},
  {"t":"Arroz con calabaza y pollo desmenuzado","tempo":"30 min","por":"3 raciones","ing":["2 cucharadas soperas de arroz","150 g de calabaza","40 g de pechuga de pollo","Un chorrito de aceite de oliva"],"passos":["Cuece el pollo en agua durante 15 minutos y desmenúzalo muy fino.","En la misma agua, cuece el arroz con la calabaza en dados hasta que quede cremoso.","Añade el pollo, chafa con un tenedor e incorpora el aceite."]},
  {"t":"Tiritas de tortilla de espinacas","tempo":"10 min","por":"1 ración","ing":["1 huevo","1 puñado de espinacas picadas","Un chorrito de aceite de oliva"],"passos":["Bate el huevo y mézclalo con las espinacas bien picadas.","Cuaja en una sartén con un chorrito de aceite de oliva, a fuego lento, por los dos lados.","Comprueba que el huevo esté bien cuajado y corta en tiritas fáciles de agarrar."]},
  {"t":"Tortitas de plátano y avena","tempo":"15 min","por":"6 tortitas","ing":["1 plátano maduro","1 huevo","3 cucharadas soperas de copos de avena"],"passos":["Chafa el plátano y mézclalo con el huevo y la avena.","Cocina cucharadas pequeñas en una sartén antiadherente, 2 minutos por cada lado.","Deja enfriar y corta en tiras. Sin azúcar: el plátano ya endulza."]},
  {"t":"Bastones de boniato al horno","tempo":"30 min","por":"2 raciones","ing":["1 boniato","Un chorrito de aceite de oliva","Una pizca de pimentón dulce (opcional)"],"passos":["Precalienta el horno a 200 °C.","Corta el boniato en bastones del grosor de un dedo.","Úntalos con el aceite y el pimentón y ásalos de 20 a 25 minutos, hasta que estén tiernos por dentro."]},
  {"t":"Bolitas de garbanzos y zanahoria","tempo":"30 min","por":"10 bolitas","ing":["150 g de garbanzos cocidos sin sal","1 zanahoria rallada fina","2 cucharadas soperas de copos de avena","Perejil picado"],"passos":["Precalienta el horno a 190 °C.","Chafa los garbanzos y mézclalos con la zanahoria, la avena y el perejil.","Forma bolitas aplanadas y hornea 18 minutos, dándoles la vuelta a mitad de cocción."]},
  {"t":"Pasta con boloñesa de lentejas","tempo":"30 min","por":"4 raciones","ing":["60 g de pasta pequeña","3 cucharadas soperas de lentejas rojas","1 zanahoria rallada","200 g de tomate pelado sin sal","1/4 de cebolla","Un chorrito de aceite de oliva"],"passos":["Dora la cebolla picada en el aceite y añade la zanahoria.","Añade las lentejas, el tomate y un vaso de agua. Cuece 20 minutos.","Cuece la pasta aparte y mézclala con la salsa. Chafa un poco, si hace falta."]},
  {"t":"Merluza desmenuzada con arroz de zanahoria","tempo":"25 min","por":"3 raciones","ing":["60 g de merluza sin piel ni espinas","3 cucharadas soperas de arroz","1 zanahoria rallada","Un chorrito de aceite de oliva"],"passos":["Cuece el arroz con la zanahoria rallada en agua hasta que quede tierno.","Cuece la merluza al vapor 8 minutos y sepárala en lascas, comprobando que no tenga espinas.","Mezcla todo con el aceite."]},
  {"t":"Yogur natural con fruta chafada","tempo":"5 min","por":"1 ración","ing":["1 yogur natural sin azúcar","1/2 melocotón maduro o 4 fresas","1 cucharadita de copos de avena finos (opcional)"],"passos":["Chafa la fruta con un tenedor.","Mézclala con el yogur.","Espolvorea con la avena. Es una merienda rápida y sin azúcar."]},
  {"t":"Hamburguesas de pollo y calabacín","tempo":"30 min","por":"8 mini hamburguesas","ing":["150 g de pollo picado","1/2 calabacín rallado y escurrido","2 cucharadas soperas de pan rallado","Perejil picado"],"passos":["Precalienta el horno a 190 °C.","Mezcla todo y forma hamburguesas pequeñas y aplanadas.","Hornea de 18 a 20 minutos, dándoles la vuelta a mitad de cocción, hasta que estén bien hechas por dentro.","Corta en tiras para que el bebé pueda agarrarlas."]},
  {"t":"Arroz con tomate y pavo","tempo":"30 min","por":"3 raciones","ing":["3 cucharadas soperas de arroz","2 tomates maduros sin piel","50 g de pechuga de pavo","1/4 de cebolla","Un chorrito de aceite de oliva"],"passos":["Dora la cebolla picada en el aceite y añade el tomate picado.","Añade el pavo en dados pequeños, el arroz y el doble de agua.","Cuece 20 minutos, hasta que el arroz quede caldoso y el pavo bien hecho."]},
  {"t":"Magdalenas de manzana y zanahoria","tempo":"30 min","por":"10 magdalenas pequeñas","ing":["1 manzana rallada","1 zanahoria rallada","1 huevo","80 g de copos de avena triturados","1 cucharadita de levadura química","Canela"],"passos":["Precalienta el horno a 180 °C.","Mezcla todos los ingredientes hasta obtener una masa húmeda.","Llena moldes pequeños hasta la mitad y hornea 20 minutos.","Sin azúcar ni miel: es la fruta la que endulza."]},
  {"t":"Ramilletes de brócoli con queso fresco","tempo":"10 min","por":"1 ración","ing":["5 ramilletes de brócoli","5 ramilletes de coliflor","1 cucharada sopera de queso fresco"],"passos":["Cuece los ramilletes al vapor de 7 a 8 minutos, hasta que estén bien tiernos.","Deja enfriar y sírvelos enteros, con el \"tallo\" para que el bebé los agarre.","Úntalos con un poco de queso fresco chafado."]},
  {"t":"Croquetas de merluza al horno","tempo":"35 min","por":"10 croquetas","ing":["100 g de merluza cocida, sin espinas","1 patata cocida","1 huevo","Perejil picado"],"passos":["Precalienta el horno a 190 °C.","Chafa la patata con la merluza en lascas, el huevo y el perejil.","Forma las croquetas y hornea 20 minutos, hasta que se doren."]},
  {"t":"Gachas de avena con yogur y arándanos","tempo":"10 min","por":"1 ración","ing":["3 cucharadas soperas de copos de avena","120 ml de la leche habitual del bebé o agua","2 cucharadas soperas de yogur natural","1 puñado de arándanos"],"passos":["Cuece la avena en el líquido durante 5 minutos.","Chafa los arándanos (enteros pueden provocar atragantamiento).","Añade el yogur y los arándanos a las gachas tibias."]},
  {"t":"Arroz con pollo y verduras","tempo":"35 min","por":"Familia (4)","ing":["200 g de arroz","2 pechugas de pollo en dados","1 zanahoria","1 puñado de guisantes","1 cebolla","Aceite de oliva y laurel"],"passos":["Dora la cebolla en el aceite con el laurel y añade el pollo.","Añade la zanahoria en dados, el arroz y el doble de agua.","A mitad de cocción, incorpora los guisantes. Sazona la parte de los adultos solo en el plato."]},
  {"t":"Curry suave de garbanzos con arroz","tempo":"30 min","por":"Familia (4)","ing":["400 g de garbanzos cocidos","1 lata de tomate pelado","100 ml de leche de coco","1 cebolla","1 cucharadita de curry suave","Arroz para acompañar"],"passos":["Dora la cebolla y añade el curry, sin picante.","Incorpora el tomate, los garbanzos y la leche de coco. Cuece 15 minutos.","Chafa un poco la ración del bebé y sirve con arroz."]},
  {"t":"Pasta con salmón y guisantes","tempo":"20 min","por":"Familia (4)","ing":["300 g de pasta corta","200 g de salmón sin piel ni espinas","150 g de guisantes","2 cucharadas soperas de queso fresco o nata de soja","Ralladura de limón"],"passos":["Cuece la pasta y añade los guisantes en los últimos 4 minutos.","Cuece el salmón al vapor y sepáralo en lascas, comprobando que no tenga espinas.","Mezcla todo con el queso fresco y la ralladura de limón."]},
  {"t":"Pastel de lentejas y boniato","tempo":"45 min","por":"Familia (4)","ing":["200 g de lentejas","2 zanahorias","1 lata de tomate pelado","3 boniatos","1 cebolla","Aceite de oliva"],"passos":["Cuece los boniatos y cháfalos con un chorrito de aceite de oliva.","Rehoga la cebolla, la zanahoria picada, el tomate y las lentejas cocidas durante 15 minutos.","Pon las lentejas en una fuente, cubre con el puré y hornea 15 minutos a 200 °C."]},
  {"t":"Pescado al horno con patatitas","tempo":"40 min","por":"Familia (4)","ing":["4 rodajas de merluza o dorada","500 g de patatitas","1 calabacín","Tomates cherry cortados en cuartos","Aceite de oliva, ajo y perejil"],"passos":["Asa las patatitas en cuartos con aceite de oliva durante 20 minutos a 200 °C.","Añade el pescado, el calabacín y el tomate. Riega con aceite de oliva, ajo y perejil.","Asa 15 minutos más. Quita bien las espinas de la ración del bebé."]},
  {"t":"Albóndigas con espaguetis","tempo":"40 min","por":"Familia (4)","ing":["400 g de carne de ternera picada","1 huevo","3 cucharadas soperas de pan rallado","1 lata de tomate pelado","1 cebolla","Espaguetis y albahaca"],"passos":["Mezcla la carne con el huevo y el pan rallado y forma albóndigas pequeñas.","Prepara una salsa con la cebolla, el tomate y la albahaca y cuece las albóndigas dentro 20 minutos.","Sirve con espaguetis. Corta las albóndigas del bebé en cuartos."]},
  {"t":"Frittata de verduras al horno","tempo":"30 min","por":"Familia (4)","ing":["6 huevos","1 calabacín","1 pimiento rojo","1 puñado de espinacas","50 g de queso rallado"],"passos":["Precalienta el horno a 180 °C.","Saltea las verduras picadas en un chorrito de aceite de oliva.","Bate los huevos con el queso, añade las verduras y hornea 20 minutos.","Corta en cuadrados: sírvela caliente o fría, en la fiambrera."]},
  {"t":"Tortitas de yogur y manzana","tempo":"20 min","por":"10 tortitas","ing":["1 yogur natural","1 huevo","80 g de harina","1 cucharadita de levadura química","1 manzana rallada","Canela"],"passos":["Mezcla el yogur, el huevo, la harina y la levadura.","Añade la manzana rallada y la canela.","Cocina cucharadas en una sartén antiadherente, 2 minutos por cada lado."]},
  {"t":"Wraps de pollo y aguacate","tempo":"15 min","por":"Familia (4)","ing":["4 tortillas de trigo","2 pechugas de pollo a la plancha","1 aguacate","Tomate y lechuga","Queso fresco"],"passos":["Chafa el aguacate con el queso fresco.","Unta las tortillas y añade el pollo en tiras, el tomate y la lechuga.","Enrolla y corta en rodajas pequeñas para el bebé."]},
  {"t":"Sopa de alubias con col","tempo":"40 min","por":"Familia (6)","ing":["400 g de alubias cocidas","2 patatas","2 zanahorias","1 cebolla","2 hojas de col picuda en juliana fina","Aceite de oliva"],"passos":["Cuece la patata, la zanahoria, la cebolla y la mitad de las alubias durante 25 minutos y tritura.","Añade el resto de las alubias y la col y cuece 10 minutos más.","Riega con aceite de oliva en crudo. La col debe quedar bien tierna para el bebé."]},
  {"t":"Pizza de tortilla de trigo con verduras","tempo":"15 min","por":"2 pizzas pequeñas","ing":["2 tortillas de trigo","4 cucharadas soperas de tomate triturado sin sal","Calabacín y pimiento en láminas finas","60 g de mozzarella","Orégano"],"passos":["Precalienta el horno a 200 °C.","Unta las tortillas con tomate, añade las verduras y la mozzarella.","Hornea de 8 a 10 minutos y corta en tiras para el bebé."]},
  {"t":"Magdalenas de plátano sin azúcar","tempo":"30 min","por":"12 magdalenas","ing":["2 plátanos bien maduros","2 huevos","150 g de copos de avena triturados","1 cucharadita de levadura química","Canela"],"passos":["Precalienta el horno a 180 °C.","Chafa los plátanos y mézclalos con los huevos, la avena, la levadura y la canela.","Hornea en moldes de magdalenas durante 20 minutos."]},
  {"t":"Risotto de champiñones y guisantes","tempo":"35 min","por":"Familia (4)","ing":["250 g de arroz redondo","200 g de champiñones picados","150 g de guisantes","1 cebolla","1 litro de caldo de verduras casero sin sal","Queso rallado"],"passos":["Dora la cebolla y los champiñones en un chorrito de aceite de oliva.","Añade el arroz y ve incorporando el caldo caliente, removiendo, durante 18 minutos.","Al final, añade los guisantes y el queso. Pica bien los champiñones de la ración del bebé."]},
  {"t":"Judías verdes rebozadas al horno","tempo":"30 min","por":"Familia (4)","ing":["300 g de judías verdes","2 huevos","4 cucharadas soperas de harina","Un chorrito de aceite de oliva"],"passos":["Cuece las judías verdes 6 minutos y escúrrelas bien.","Pásalas por la harina y por el huevo batido.","Ásalas en una bandeja untada con aceite de oliva, 15 minutos a 200 °C. Más ligeras que fritas."]}
];
